update public.regulation_sections set heading=''
where document_id in (select id from public.regulation_documents where document_code='DP-SR-HR-001' and is_shared_standard=true);

update public.regulation_sections set content_text=$t$
การลงโทษด้วยการเตือนด้วยวาจาและบันทึกไว้
การว่ากล่าวตักเตือนด้วยวาจา จะกระทำโดยผู้บังคับบัญชาโดยตรงของผู้กระทำผิด ความผิดในขั้นนี้ไม่ร้ายแรง และไม่ก่อให้เกิดผลเสียหายแก่บริษัท
ผู้จัดการฝ่ายบริหารทรัพยากรบุคคลจะเป็นผู้ให้คำปรึกษาแนะนำ และฝ่ายบริหารทรัพยากรบุคคลจะจัดเตรียมเอกสารการลงโทษให้กับผู้บังคับบัญชา โดยระบุรายละเอียดเกี่ยวกับการกระทำผิด ซึ่งจะประกอบด้วย ผู้กระทำผิด, ลักษณะของความผิด, สถานที่กระทำผิด, วันที่กระทำผิด และให้ผู้บังคับบัญชาโดยตรง เป็นผู้ว่ากล่าวตักเตือนพนักงานผู้กระทำผิด และให้พนักงานผู้กระทำผิดลงนามยอมรับเกี่ยวกับการกระทำผิดของตน แล้วจัดส่งเอกสารมาเก็บที่ฝ่ายบริหารทรัพยากรบุคคล
$t$ where section_number='10.6.1' and document_id=(select id from public.regulation_documents where document_code='DP-SR-HR-001' and is_shared_standard=true limit 1);

update public.regulation_sections set content_text=$t$
การลงโทษด้วยการเตือนเป็นหนังสือ
เป็นการลงโทษหลังจากที่การตักเตือนด้วยวาจาไม่ประสบผลหรือมีการกระทำความผิดรุนแรงเกินกว่าจะตักเตือนด้วยวาจา หรือทำผิดซ้ำเรื่องเดิมในเวลาไล่เลี่ยกัน และยังอยู่ในระยะเวลาตามกำหนดของการลงโทษ ซึ่งความผิดดังกล่าวยังไม่ก่อให้เกิดความเสียหายร้ายแรง หรือผลเสียหายโดยตรงต่อบริษัท แต่อาจก่อให้เกิดความรำคาญกับผู้เกี่ยวข้อง หรือเกิดความล่าช้าในการปฏิบัติงาน การพิจารณาการลงโทษในชั้นนี้ เป็นอำนาจของผู้บังคับบัญชาของผู้กระทำผิด โดยผู้จัดการฝ่ายบริหารทรัพยากรบุคคลจะเป็นผู้ให้คำปรึกษาแนะนำ และฝ่ายบริหารทรัพยากรบุคคลจะจัดเตรียมเอกสารการลงโทษให้กับผู้บังคับบัญชา โดยระบุรายละเอียดเกี่ยวกับการกระทำผิด ซึ่งจะประกอบด้วย ผู้กระทำผิด, ลักษณะของความผิด, สถานที่กระทำผิด, วันที่กระทำผิด และให้ผู้บังคับบัญชาโดยตรง เป็นผู้ว่ากล่าวตักเตือนพนักงานผู้กระทำผิด และให้พนักงานผู้กระทำผิดลงนามยอมรับเกี่ยวกับการกระทำผิดของตน แล้วจัดส่งเอกสารมาเก็บที่ฝ่ายบริหารทรัพยากรบุคคล
$t$ where section_number='10.6.2' and document_id=(select id from public.regulation_documents where document_code='DP-SR-HR-001' and is_shared_standard=true limit 1);

update public.regulation_sections set content_text=$t$
การลงโทษด้วยการพักงานไม่จ่ายค่าจ้าง ไม่เกิน 6 วัน
เป็นการลงโทษที่รุนแรงกว่าการเตือนด้วยวาจาและการเตือนเป็นหนังสือ ผู้กระทำผิดที่ถูกลงโทษในขั้นนี้เมื่อปรากฏเจตนาชัดแจ้งในการกระทำผิด หรือเป็นการทำผิดวินัยซ้ำในเรื่องเดิมบ่อย ๆ ภายในระยะเวลาไล่เลี่ยกัน และยังอยู่ในเวลาตามกำหนดของการลงโทษ และความผิดดังกล่าวก่อให้เกิดความเสียหายต่อบริษัท ไม่ว่าจะเป็นด้านทรัพย์สินหรือชื่อเสียงก็ตาม
การลงโทษในลักษณะนี้ ต้องดำเนินการเป็นขั้น ๆ ดังนี้
ขั้นที่ 1 ผู้บังคับบัญชาโดยตรงจะต้องบันทึกรายละเอียดเกี่ยวกับความผิด เหตุผลในการลงโทษในลักษณะนี้ สรุปผลการสอบสวนส่งให้ผู้บังคับบัญชาระดับเหนือกว่า เพื่อพิจารณา
ขั้นที่ 2 ผู้บังคับบัญชาระดับเหนือกว่า จะต้องพิจารณาเรื่องราว ร่วมกับผู้จัดการฝ่ายบริหารทรัพยากรบุคคลโดยการสอบสวนหาข้อเท็จจริงจากผู้ที่เกี่ยวข้อง เพื่อพิจารณาให้ความเป็นธรรมมากที่สุด หากพบว่าพนักงานกระทำความผิดจริงจึงจะเสนอเรื่องราวต่อไปยังผู้บังคับบัญชาสูงสุดของหน่วยงานเพื่อพิจารณา
ขั้นที่ 3 ฝ่ายบริหารทรัพยากรบุคคลจัดเตรียมหนังสือแจ้งการลงโทษ โดยลงนามรับรองแจ้งการลงโทษ และส่งต่อให้กับผู้บังคับบัญชาระดับผู้จัดการของพนักงานผู้กระทำผิด เพื่อให้พนักงานผู้กระทำผิดลงนามยอมรับผิดในหนังสือ และเมื่อพนักงานผู้กระทำผิดลงนามยอมรับแล้ว ให้ส่งเอกสารคืนกลับมาที่ฝ่ายบริหารทรัพยากรบุคคล
$t$ where section_number='10.6.3' and document_id=(select id from public.regulation_documents where document_code='DP-SR-HR-001' and is_shared_standard=true limit 1);

update public.regulation_sections set content_text=$t$
การลงโทษด้วยการเลิกจ้างโดยไม่จ่ายค่าชดเชย
การลงโทษทางวินัยในขั้นนี้ จะกระทำเมื่อได้มีการลงโทษด้วยวาจา, เตือนเป็นหนังสือ, หรือพักงานโดยไม่ได้รับค่าจ้าง ในลักษณะเดิมและไม่ประสบผล ยกเว้นพนักงานกระทำความผิดขั้นร้ายแรง แม้จะเป็นการกระทำผิดครั้งแรกก็ตาม การลงโทษทางวินัยลักษณะนี้จะกระทำเป็นขั้น ๆ ดังนี้
ขั้นที่ 1- ขั้นที่ 2 กระทำเช่นเดียวกับการลงโทษทางวินัยข้อ 10.6.3
ขั้นที่ 3 ผู้บังคับบัญชาระดับสูงสุดของหน่วยงานที่ผู้กระทำผิดสังกัดอยู่ จะพิจารณาเรื่องทั้งหมดอีกครั้งหนึ่ง หากเห็นสมควรลงโทษขั้นเลิกจ้างโดยไม่จ่ายค่าชดเชย จึงจะส่งให้กรรมการผู้จัดการพิจารณา
ขั้นที่ 4 เมื่อกรรมการผู้จัดการพิจารณาแล้ว เห็นว่าสมควรขั้นเลิกจ้างโดยไม่จ่ายค่าชดเชย หรือลงโทษขั้นอื่นใดก็ตาม กรรมการผู้จัดการจะสั่งการผ่านผู้บังคับบัญชาสูงสุดของหน่วยงานไปยังฝ่ายบริหารทรัพยากรบุคคล เพื่อจัดเตรียมหนังสือแจ้งความผิดและลงโทษ หรือหนังสือเลิกจ้าง โดยผู้มีอำนาจลงนามคือ กรรมการผู้จัดการ หรือผู้ที่กรรมการผู้จัดการลงนามมอบหมายอย่างเป็นลายลักษณ์อักษร
$t$ where section_number='10.6.4' and document_id=(select id from public.regulation_documents where document_code='DP-SR-HR-001' and is_shared_standard=true limit 1);